// Analyze Multi-Country Arbitrage & Price Drops
const items = $input.all();
const analyzed = [];

const minOrders = 50;
const minRating = 4.5;
const minSpreadPercent = 18.0;

for (const item of items) {
  const p = item.json;

  // Basic sanity validation
  const salePrice = parseFloat(p.salePrice || p.price || 0);
  const orders = parseInt(p.ordersCount || p.orders || 0, 10);
  const rating = parseFloat(p.rating || 0);

  // Filter out promo teaser cards ($1.09 teaser prices for new accounts)
  if (salePrice < 2.50 || orders < minOrders || rating < minRating) {
    continue;
  }

  // Multi-country arbitrage calculation
  let lowestCountry = 'US';
  let lowestPrice = salePrice;
  let spreadPercent = 0;

  if (p.countryPrices && typeof p.countryPrices === 'object') {
    for (const [country, cPrice] of Object.entries(p.countryPrices)) {
      const numPrice = parseFloat(cPrice);
      if (numPrice > 0 && numPrice < lowestPrice) {
        lowestPrice = numPrice;
        lowestCountry = country;
      }
    }
    if (salePrice > 0 && lowestPrice < salePrice) {
      spreadPercent = Math.round(((salePrice - lowestPrice) / salePrice) * 100);
    }
  }

  // Price drop detection
  let priceDropPercent = 0;
  if (p.previousPrice && parseFloat(p.previousPrice) > salePrice) {
    const prev = parseFloat(p.previousPrice);
    priceDropPercent = Math.round(((prev - salePrice) / prev) * 100);
  }

  const isArbitrageOpportunity = spreadPercent >= minSpreadPercent;
  const isPriceDropOpportunity = priceDropPercent >= 15;

  if (isArbitrageOpportunity || isPriceDropOpportunity) {
    analyzed.push({
      json: {
        title: p.title,
        productUrl: p.productUrl || p.url,
        imageUrl: p.imageUrl || p.image,
        searchQuery: p.searchQuery,
        usPrice: `$${salePrice.toFixed(2)}`,
        lowestCountryPrice: `$${lowestPrice.toFixed(2)} (${lowestCountry})`,
        arbitrageSpreadPercent: `${spreadPercent}%`,
        priceDropPercent: priceDropPercent > 0 ? `${priceDropPercent}%` : 'N/A',
        ordersCount: orders,
        ratingStars: rating,
        opportunityType: isArbitrageOpportunity && isPriceDropOpportunity ? 'ARBITRAGE + PRICE DROP' : (isArbitrageOpportunity ? 'MULTI-COUNTRY ARBITRAGE' : 'PRICE DROP ALERT'),
        discoveredAt: new Date().toISOString()
      }
    });
  }
}

return analyzed;

